  var original=form.Bounds;var state=form.WindowState;var devices=new HashSet<string>();var observedDpi=new HashSet<int>();var samples=new List<object>();WorkbenchForm? workbench=form as WorkbenchForm;Form? floating=null;var createdFloat=false;
