 await Test("native photo column captions and preview split remain outside toolbar and notice",async()=>{Check(photo is not null,"Photo prerequisite missing");photo!.PerformLayout();await Task.Delay(80);var layout=AssertPhotoDockLayout(photo);Check(Grid(photo).Columns["photoThumbnail"]!.HeaderText=="사진"&&Grid(photo).Columns["title"]!.HeaderText=="사진 제목","Native photo header labels are missing");Samples.Add(layout);Capture(form,"08-photo-visible-headers");});
